using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MyDoc.Data;using MyDoc.Models;using MyDoc.Services;
namespace MyDoc.Pages;[Authorize]public sealed class IndexModel(DocSpaceDbContext db,ICurrentUserService users,IDocumentImportService importer,IDocxImportService docx):PageModel{public ApplicationUser?CurrentUser{get;private set;}public List<Document>Owned{get;private set;}=[];public List<Document>Shared{get;private set;}=[];[BindProperty]public IFormFile?ImportFile{get;set;}[BindProperty]public string?ImportTitle{get;set;}public async Task OnGetAsync(CancellationToken ct){CurrentUser=await users.GetCurrentAsync(User);if(CurrentUser is null)return;Owned=await db.Documents.Include(d=>d.Owner).Where(d=>d.OwnerId==CurrentUser.Id).ToListAsync(ct);Shared=await db.Documents.Include(d=>d.Owner).Include(d=>d.Shares).Where(d=>d.Shares.Any(s=>s.UserId==CurrentUser.Id)).ToListAsync(ct);}public async Task<IActionResult>OnPostWordAsync(CancellationToken ct){var u=await users.GetCurrentAsync(User);if(u is null)return Challenge();var r=await docx.ConvertAsync(ImportFile,ct);if(!r.Ok){TempData["Error"]=r.Error;return RedirectToPage();}var n=Path.GetFileNameWithoutExtension(ImportFile!.FileName);var d=new Document{OwnerId=u.Id,Title=n.Length>200?n[..200]:n,ContentHtml=r.Html,CreatedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow};db.Documents.Add(d);await db.SaveChangesAsync(ct);return RedirectToPage("/Documents/Edit",new{id=d.Id});}public async Task<IActionResult>OnPostCreateAsync(CancellationToken ct){var u=await users.GetCurrentAsync(User);if(u is null)return Challenge();var d=new Document{OwnerId=u.Id,CreatedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow};db.Documents.Add(d);await db.SaveChangesAsync(ct);return RedirectToPage("/Documents/Edit",new{id=d.Id});}}
